package com.ainexus.controller; import com.ainexus.dto.*; import com.ainexus.model.User; import com.ainexus.service.RecommendationService; import jakarta.servlet.http.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/recommendations") public class RecommendationController {private final RecommendationService s; public RecommendationController(RecommendationService s){this.s=s;} private User u(HttpServletRequest r){return (User)r.getAttribute("AUTH_USER");} @PostMapping("/analyze") public Map<String,Object> analyze(HttpServletRequest r,@Valid @RequestBody RequirementRequest q){return s.analyze(u(r),q);} @GetMapping("/history") public List<Map<String,Object>> history(HttpServletRequest r){return s.history(u(r));}}
